package ru.hive13.server;

import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;
import ru.hive13.model.*;
import static ru.hive13.model.Model.*;
import java.util.*;
import java.nio.file.Path;

class ExpeditionTest {
    @Test void sustainedSurfacePursuitLeadsToPhysicalRecoveryAndThenReturns(){var e=entered();var s=e.state;s.creatures.clear();s.actor(1).life=s.actor(2).life="DORMANT";var a=s.actor(0);var c=new Creature();c.id="H";c.type="ГОНЧАЯ";c.roomId=c.home="V0";c.x=a.x+5;c.y=a.y;c.exertion=99.9;s.creatures.add(c);var start=c.positionForDefense();e.advance(.1);assertEquals("RECOVERING",c.state);assertTrue(c.recoveryUntil>s.gameTime+34);assertEquals(100,a.hp);e.advance(1);assertTrue(start.distance(c.positionForDefense())>1);assertEquals(1,s.creatures.size());s.gameTime=c.recoveryUntil+.01;e.advance(.1);assertNotEquals("RECOVERING",c.state);assertEquals(1,s.creatures.size());}
    @Test void medicineActuallyGivesPersonalKitsAndRespectsCapacity(){var e=entered();int before=DefenseRules.count(e.state.actor(0),"medkit");use(e,"pharmacy","MEDICINE");assertEquals(before+2,DefenseRules.count(e.state.actor(0),"medkit"));var full=entered();full.state.actor(0).inventory.put("ballast",new Item("ballast","Груз",1,17));var f=WorldObjects.get(full.state,"pharmacy");assertFalse(WorldObjects.offer(full.state,full.state.actor(0),f,"MEDICINE").enabled());assertFalse(full.state.flags.contains("surface_medicine"));}
    @Test void previousLocationKeepsItsCreaturesWithoutLeakingThemToClients(){var e=entered();assertEquals(2,e.state.visitedLocations.get("object13").creatures.size());assertTrue(e.state.visitedLocations.get("object13").rooms.containsKey("B4"));assertTrue(e.view(0).visitedLocations.isEmpty());assertEquals(1,e.state.visitedLocations.size());}
    @Test void longCorridorGateHasUsablePanelsOnBothSides(){var e=entered();var a=e.state.actor(0);var d=e.state.doors.get("E06");a.roomId=d.b;a.x=d.pb.x();a.y=d.pb.y();var r=e.command(0,new Packet("INTERACT",UUID.randomUUID().toString(),Map.of("target",d.id,"action","CLOSE")));assertTrue(r.accepted(),r.reason());assertFalse(d.passable());}
    @Test void findingTheIndependentJournalAfterTheArchiveAlsoProvesTheLie(){var e=entered();use(e,"field_grid","GRID_RESET");use(e,"sigma","SIGMA_TUNE");e.state.flags.add("archive_authorized");use(e,"station_archive","STATION_ARCHIVE");use(e,"pharmacy","MEDICINE");assertTrue(e.state.flags.contains("ai_lies_proved"));}
    @Test void surfaceCacheSupportsThreeArmedPlayersAndTheArchiveVote(){var e=entered();e.state.supplies.put("batteries",0);use(e,"field_store","FIELD_SUPPLY");assertEquals(3,e.state.supplies.get("batteries"));e.state.flags.add("sigma_online");ExpeditionSystem.options(e);assertTrue(e.state.options.stream().anyMatch(o->o.id.equals("archive_authorized")&&o.enabled));}
    private GameEngine ended(){var s=WorldFactory.create("STORY");s.phase=Phase.GAME_OVER;s.flags.add("surface_reached");for(var a:s.actors){a.connected=true;a.life="EVACUATED";}return new GameEngine(s);}
    private GameEngine entered(){var e=ended();for(int i=0;i<3;i++)assertTrue(ExpeditionSystem.continueChapter(e,i).accepted());return e;}
    private void use(GameEngine e,String id,String operation){var a=e.state.actor(0);var f=WorldObjects.get(e.state,id);a.roomId=f.room();a.x=f.x();a.y=f.y();e.state.creatures.clear();var result=ObjectActions.order(e,a,id,operation);assertTrue(result.accepted(),result.reason());e.advance(20);if(e.state.phase==Phase.VOTING){e.state.phase=Phase.ACTION;e.state.remaining=60;}}
    @Test void everyoneMustConfirmAndTravelPreservesConsequences(){var e=ended();e.state.actor(0).hp=61;e.state.flags.add("lina_lost");assertTrue(ExpeditionSystem.continueChapter(e,0).accepted());assertEquals(1,e.state.currentAct);assertTrue(ExpeditionSystem.continueChapter(e,1).accepted());assertEquals(1,e.state.currentAct);assertTrue(ExpeditionSystem.continueChapter(e,2).accepted());assertEquals(2,e.state.currentAct);assertEquals(61,e.state.actor(0).hp);assertTrue(e.state.flags.contains("lina_lost"));assertEquals("V0",e.state.actor(0).roomId);assertEquals(Phase.ACTION,e.state.phase);assertFalse(e.state.rooms.containsKey("B4"));}
    @Test void allSurfaceObjectsAndDoorsAreNavigable(){var e=entered();for(var f:WorldObjects.all(e.state))assertTrue(e.state.rooms.get(f.room()).contains(f.x(),f.y()),f.id());for(var a:e.state.rooms.values())for(var b:e.state.rooms.values())assertNotNull(Pathfinder.find(e.state,a.id,a.center(),b.id,b.center()));}
    @Test void surfaceMissionsRequireRealPrerequisites(){var e=entered();assertFalse(WorldObjects.offer(e.state,e.state.actor(0),WorldObjects.get(e.state,"sigma"),"SIGMA_TUNE").enabled());use(e,"field_grid","GRID_RESET");assertTrue(e.state.flags.contains("surface_grid"));use(e,"sigma","SIGMA_TUNE");assertTrue(e.state.flags.contains("sigma_online"));assertFalse(WorldObjects.offer(e.state,e.state.actor(0),WorldObjects.get(e.state,"station_archive"),"STATION_ARCHIVE").enabled());assertTrue(e.state.progress.get("scientist_deadline")>e.state.gameTime);}
    @Test void scientistDeadlineHasARealIrreversibleOutcome(){var e=entered();use(e,"field_grid","GRID_RESET");use(e,"sigma","SIGMA_TUNE");e.state.gameTime=e.state.progress.get("scientist_deadline")+1;ExpeditionSystem.update(e);assertEquals("DEAD",e.state.npcs.get("scientist").condition);assertTrue(e.state.flags.contains("scientist_lost"));e.state.flags.add("rescue_authorized");assertFalse(WorldObjects.offer(e.state,e.state.actor(0),WorldObjects.get(e.state,"scientist"),"SCIENTIST").enabled());}
    @Test void independentDocumentsAreNeededToProveTheLie(){var e=entered();use(e,"field_grid","GRID_RESET");use(e,"sigma","SIGMA_TUNE");e.state.flags.add("archive_authorized");use(e,"station_archive","STATION_ARCHIVE");assertFalse(e.state.flags.contains("ai_lies_proved"));var other=entered();use(other,"pharmacy","MEDICINE");use(other,"field_grid","GRID_RESET");use(other,"sigma","SIGMA_TUNE");other.state.flags.add("archive_authorized");use(other,"station_archive","STATION_ARCHIVE");assertTrue(other.state.flags.contains("ai_lies_proved"));}
    @Test void saveKeepsSurfaceGeometryAndPersonalReadiness(@TempDir Path dir)throws Exception{var e=entered();e.state.chapterReady.add(1);e.state.flags.add("caravan_saved");var file=dir.resolve("surface.json");SaveStore.save(file,e.state);var s=SaveStore.load(file);assertEquals(2,s.currentAct);assertEquals("vector_sigma",s.location);assertEquals(8,s.doors.size());assertTrue(s.flags.contains("caravan_saved"));assertTrue(s.chapterReady.contains(1));assertTrue(s.rooms.containsKey("V6"));}
}
